import type { VpnStatus } from '@ragenet/core';

export interface StartVpnOptions {
  /** Xray JSON as generated by `buildXrayConfig`. */
  config: string;
  /** Per-app split tunneling on Android. */
  allowedPackages?: string[];
  disallowedPackages?: string[];
  killSwitch?: boolean;
  mtu?: number;
  dns?: string[];
}

export type VpnEventListener = (status: VpnStatus) => void;

/**
 * The only surface UI code should use for the tunnel.
 *
 * Android/iOS implement this over an Expo module; desktop implements it over
 * Tauri commands that supervise the Xray sidecar.
 */
export interface VpnBridge {
  prepare(): Promise<boolean>;
  start(options: StartVpnOptions): Promise<void>;
  stop(): Promise<void>;
  getStatus(): Promise<VpnStatus>;
  subscribe(listener: VpnEventListener): () => void;
}
